window.ScripturaLexicons.BDAG_PART_0351 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-01\" data-source=\"BDAG\" data-search=\"σχισμή, ῆς, ἡ substantivo feminino rachadura; fissura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχισμή, ῆς, ἡ</td><td>substantivo feminino</td><td>rachadura; fissura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-02\" data-source=\"BDAG\" data-search=\"σχοινίον, ου, τό substantivo neutro corda; cordão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχοινίον, ου, τό</td><td>substantivo neutro</td><td>corda; cordão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-03\" data-source=\"BDAG\" data-search=\"σχοίνισμα, ατος, τό substantivo neutro quinhão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχοίνισμα, ατος, τό</td><td>substantivo neutro</td><td>quinhão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-04\" data-source=\"BDAG\" data-search=\"σχολάζω verbo dedicar-se; estar desocupado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχολάζω</td><td>verbo</td><td>dedicar-se; estar desocupado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-05\" data-source=\"BDAG\" data-search=\"σχολή, ῆς, ἡ substantivo feminino sala de preleções BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχολή, ῆς, ἡ</td><td>substantivo feminino</td><td>sala de preleções</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-06\" data-source=\"BDAG\" data-search=\"σχῶ remissão ver ἔχω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχῶ</td><td>remissão</td><td>ver ἔχω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-07\" data-source=\"BDAG\" data-search=\"σῴζω verbo salvar; resgatar; preservar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σῴζω</td><td>verbo</td><td>salvar; resgatar; preservar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-08\" data-source=\"BDAG\" data-search=\"Σωκράτης, ους, ὁ nome próprio masculino Sócrates BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σωκράτης, ους, ὁ</td><td>nome próprio masculino</td><td>Sócrates</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-09\" data-source=\"BDAG\" data-search=\"σῶμα, ατος, τό substantivo neutro corpo; realidade; comunidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σῶμα, ατος, τό</td><td>substantivo neutro</td><td>corpo; realidade; comunidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-10\" data-source=\"BDAG\" data-search=\"σωματεῖον, ου, τό substantivo neutro vida corporativa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σωματεῖον, ου, τό</td><td>substantivo neutro</td><td>vida corporativa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-11\" data-source=\"BDAG\" data-search=\"σωματικός, ή, όν adjetivo corporal; corpóreo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σωματικός, ή, όν</td><td>adjetivo</td><td>corporal; corpóreo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-12\" data-source=\"BDAG\" data-search=\"σωματικῶς advérbio corporalmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σωματικῶς</td><td>advérbio</td><td>corporalmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-13\" data-source=\"BDAG\" data-search=\"σωμάτιον, ου, τό substantivo neutro pequeno corpo; corpo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σωμάτιον, ου, τό</td><td>substantivo neutro</td><td>pequeno corpo; corpo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-14\" data-source=\"BDAG\" data-search=\"Σώπατρος, ου, ὁ nome próprio masculino Sópatro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σώπατρος, ου, ὁ</td><td>nome próprio masculino</td><td>Sópatro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-15\" data-source=\"BDAG\" data-search=\"σωρεύω verbo amontoar; sobrecarregar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σωρεύω</td><td>verbo</td><td>amontoar; sobrecarregar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-16\" data-source=\"BDAG\" data-search=\"Σωσθένης, ους, ὁ nome próprio masculino Sóstenes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σωσθένης, ους, ὁ</td><td>nome próprio masculino</td><td>Sóstenes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-17\" data-source=\"BDAG\" data-search=\"Σωσίπατρος, ου, ὁ nome próprio masculino Sosípatro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σωσίπατρος, ου, ὁ</td><td>nome próprio masculino</td><td>Sosípatro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-18\" data-source=\"BDAG\" data-search=\"σωτήρ, ῆρος, ὁ substantivo masculino salvador; libertador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σωτήρ, ῆρος, ὁ</td><td>substantivo masculino</td><td>salvador; libertador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-19\" data-source=\"BDAG\" data-search=\"σωτηρία, ας, ἡ substantivo feminino libertação; salvação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σωτηρία, ας, ἡ</td><td>substantivo feminino</td><td>libertação; salvação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0351-20\" data-source=\"BDAG\" data-search=\"σωτήριος, ον adjetivo e substantivo neutro salvífico; meio de libertação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σωτήριος, ον</td><td>adjetivo e substantivo neutro</td><td>salvífico; meio de libertação</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0351-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχισμή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχισμή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">σχίζω</span>) rachadura, fissura (Rhet. Gr. I 552, 4; LXX) em pedras (cf. Is 2:19, 21; SibOr 3, 607) Hv 3, 2, 8; 3, 6, 3; Hs 9, 6, 4; 9, 8, 3f; 9, 23, 1–3; em varas Hs 8, 1, 9f; 14; 8, 4, 6; 8, 5, 1; 4f; 8, 7, 1f; 4; 8, 10, 1; numa montanha (Jon 2:6) Hs 9, 1, 7.—DELG s.v. <span class=\"greek\">σχίζω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχοινίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχοινίον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hdt. et al.; inscr., pap., LXX; PsSol 2:20; TestSol 4:12; JosAs; ApcrEzk [Epiph 70, 10]; Jos., Ant. 8, 385; 19, 346) corda ou cordão (originalmente de juncos, depois geralmente de outro material); usado para elevar algo IEph 9:1. Das cordas que mantêm o bote de um navio em seu lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:32</a>. Jesus as usa para fazer um chicote <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:15</a>.—B. 549. DELG s.v. <span class=\"greek\">σχοῖνος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχοίνισμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχοίνισμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (LXX) lit. ‘uma porção de terra medida por meio de uma corda de medir (<span class=\"greek\">σχοῖνος</span>, <span class=\"greek\">σχοινίον</span>)’, em nossa literatura somente em linguagem figurada quinhão (Hesych.; Etym. Mag. p. 740, 46) <span class=\"greek\">σχ</span>. <span class=\"greek\">κληρονομίας</span> <span class=\"greek\">αὐτοῦ</span> o quinhão que adquiriu 1 Cl 29:2 (Dt 32:9).—DELG s.v. <span class=\"greek\">σχοῖνος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχολάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχολάζω</span> (<span class=\"greek\">σχολή</span>) 1 aor. <span class=\"greek\">ἐσχόλασα</span> (Aeschyl., Thu. et al.; inscr., pap., LXX; TestSol 1:10 L; TestJob 6:3, 7; TestJud 20:1; Philo; em geral, de liberação de obrigação habitual ou premente; guerras, por ex., não permitem lazer Pla., Leg. 694e)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> ter tempo ou lazer para, ocupar-se com, dedicar-se a, consagrar seu tempo a <span class=\"greek\">τινί</span> alguém ou algo (Lucian, Ver. Hist. 2, 15; Ps.-Lucian, Macrob. 4 <span class=\"greek\">φιλοσοφίᾳ</span>; Epict. 2, 14, 28; Herodian 1, 8, 1 al.; SIG 717, 34f [100 a.C.] <span class=\"greek\">τοῖς</span> <span class=\"greek\">φιλοσόφοις</span>; OGI 569, 23 <span class=\"greek\">θεῶν</span> <span class=\"greek\">θρησκείᾳ</span>; Sb 4284, 15 <span class=\"greek\">τῇ</span> <span class=\"greek\">γῇ</span>; PAmh 82, 6 <span class=\"greek\">γεωργίᾳ</span>; Philo, Spec. Leg. 3, 1 al.; TestJud 20:1) <span class=\"greek\">τῇ</span> <span class=\"greek\">προσευχῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a> (sobre este assunto v. TestNapht 8:8); cf. IPol 1:3. <span class=\"greek\">Χριστιανὸς</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">σχολάζει</span> 7:3 (cf. a carta de um politeísta Sb 4515 <span class=\"greek\">οὐ</span> <span class=\"greek\">μέλλω</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">σχολάζειν</span>, <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πρότερον</span> <span class=\"greek\">ἀπαρτίσω</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱόν</span> <span class=\"greek\">μου</span> ‘não pretendo ter tempo para uma divindade antes de primeiramente educar meu filho’).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> estar sem ocupantes, estar desocupado, permanecer vazio (Plut., C. Gracch. 840 [12, 6] <span class=\"greek\">τόπος</span>; Julian, Caes. 316c <span class=\"greek\">καθέδρα</span>; SEG XI, 121, 13) de uma casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:25</a> v.l. HNyberg, Ntl. Sem. zu Uppsala 4, ’36, 22–35, ConNeot 13, ’49, 1–11.—DELG s.v. <span class=\"greek\">σχολή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχολή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχολή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Pind.+; inscr., pap., LXX, Philo, Joseph., empréstimo na literatura rabínica) primariamente ‘lazer’, que frequentemente implicava oportunidade para atividades intelectuais, especialmente por meio de preleções: sala de preleções (cf. Plut., Mor. 42a de uma escola elementar; quanto à ênfase não no local, mas na atividade intelectual em nível sofisticado, v. Dionys. Hal., Isocrates 1, Demosthenes 44; Plut., Mor. 519f, 605a; Epict. 1, 29, 34; Jos., C. Ap. 1, 53; v. New Docs 1, 129f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:9</a> (Beginn. IV 239; Bruce, coment.; et al.).—B. 1227. DELG. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχῶ</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχῶ</span> v. <span class=\"greek\">ἔχω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σῴζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σῴζω</span> fut. <span class=\"greek\">σώσω</span>; 1 aor. <span class=\"greek\">ἔσωσα</span>; perf. <span class=\"greek\">σέσωκα</span>. Pass.: imperf. <span class=\"greek\">ἐσῳζόμην</span>; fut. <span class=\"greek\">σωθήσομαι</span>; 1 aor. <span class=\"greek\">ἐσώθην</span>; perf. 3 sing. <span class=\"greek\">σέσωται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:9</a> (UPZ 122, 18 [157 a.C.] <span class=\"greek\">σέσωμαι</span>) com <span class=\"greek\">σέσῳσται</span> ou <span class=\"greek\">σέσωσται</span> como v.l. (v. Tdf. ad loc. e B-D-F §26); part. <span class=\"greek\">σεσῳσμένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:5</a>, 8 (Hom.+—<span class=\"greek\">σῴζω</span> [=<span class=\"greek\">σωί̈ζω</span>] e as formas seguramente dele derivadas devem ser escritas com <span class=\"greek\">ι</span> subscrito. Por outro lado, não é possível dizer até que ponto o <span class=\"greek\">ι</span> se estendeu do presente aos tempos formados da raiz <span class=\"greek\">σω</span>-. Kühner-Bl. II 544; B-D-F §26; Mlt-H. 84; Mayser 134)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> preservar ou resgatar de perigos e aflições naturais, salvar, proteger de dano, preservar, resgatar (X., An. 3, 2, 10 <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> … <span class=\"greek\">ἱκανοί</span> <span class=\"greek\">εἰσι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">μεγάλους</span> <span class=\"greek\">ταχὺ</span> <span class=\"greek\">μικροὺς</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">μικροὺς</span> <span class=\"greek\">σῴζειν</span>; Musonius p. 32, 10; Chion, Ep. 11; 12 <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σῴζοντος</span> <span class=\"greek\">πλευσοῦμαι</span>; Ar. [Milne 74, 15]).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> salvar da morte (inscr. [I a.C.]: Sb 8138, 34 <span class=\"greek\">σῴζονθ</span>’ <span class=\"greek\">οὗτοι</span> <span class=\"greek\">ἅπαντες</span> que invocam Ísis na hora da morte) <span class=\"greek\">τινά</span> alguém (Apollon. Rhod. 3, 323 <span class=\"greek\">θεός</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἅμμ</span>’ [=<span class=\"greek\">ἡμᾶς</span>] <span class=\"greek\">ἐσάωσεν</span> do perigo de morte no mar; Diod S 11, 92, 3; PsSol 13:2 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ῥομφαίας</span> [cf. Ps 21:21]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:30</a>; 27:40, 42, 49; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:30f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:35a</a>b, 37, 39; 1 Cl 16:16 (Ps 21:9); 59, 4; AcPl Ha 5, 12. Pass. (TestJob 19:2 <span class=\"greek\">πῶς</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">ἐσώθῃς</span>;) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:12</a> (<span class=\"greek\">ἐγερθήσεται</span> P75); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:20</a>, 31; 1 Cl 7:6. Abs., com acus. facilmente subentendido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:25</a>. <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">σῶσαι</span> salvar uma vida (Achilles Tat. 5, 22, 6; PTebt 56, 11 [II a.C.] <span class=\"greek\">σῶσαι</span> <span class=\"greek\">ψυχὰς</span> <span class=\"greek\">πολλάς</span>; EpArist 292; Jos., Ant. 11, 255) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:9</a>; 21:19 v.l. <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">σῶσαι</span> salvar a própria vida (Gen 19:17; 1 Km 19:11; Jer 31:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:35a</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:24a</a> (sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:35b</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:24b</a> v. 2a<span class=\"greek\">β</span> abaixo); 17:33 v.l. (PGM 5, 140 <span class=\"greek\">κύριε</span> [um deus] <span class=\"greek\">σῶσον</span> <span class=\"greek\">ψυχήν</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> com <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> tirar em segurança de uma situação repleta de perigo mortal (X., An. 3, 2, 11; SIG 1130, 1 <span class=\"greek\">ἐκ</span> <span class=\"greek\">κινδύνων</span>; OGI 69, 4; JosAs 4:8 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λιμοῦ</span>; 28:16 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀργῆς</span>; Jos., C. Ap. 1, 286) <span class=\"greek\">ἐκ</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">Αἰγύπτου</span> Jd 5. <span class=\"greek\">ἐκ</span> <span class=\"greek\">χειρὸς</span> <span class=\"greek\">Φαραώ</span> AcPl Ha 8, 11; <span class=\"greek\">ἐκ</span> <span class=\"greek\">Σοδόμων</span> 1 Cl 11:1 (Pla., Gorg. 511d <span class=\"greek\">ἐξ</span> <span class=\"greek\">Αἰγίνης</span> <span class=\"greek\">δεῦρο</span>). <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὥρας</span> <span class=\"greek\">ταύτης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:27</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">θανάτου</span> da (ameaça de) morte (Hom. et al.; Pla., Gorg. 511c; UPZ 122, 18 [157 a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:7</a>.—Dos dias maus da última tribulação <span class=\"greek\">ἐν</span> <span class=\"greek\">αἷς</span> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">σωθησόμεθα</span> B 8:6; cf. 1 Cl 59:4.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> salvar/libertar de doença (Hippocr., Coacae Praenotiones 136 vol. 5 p. 612 L.; IG2, 1028, 89 [I a.C.]; Mitt-Wilck. I/2, 68, 32 [132 a.C.]: deuses trazem cura) ou de possessão por espíritos hostis <span class=\"greek\">τινά</span> alguém <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">σου</span> <span class=\"greek\">σέσωκέν</span> <span class=\"greek\">σε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:22a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:34</a>; 10:52; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:48</a>; 17:19; 18:42. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:15</a>; AcPl Ha 5, 31. Pass. ser restabelecido na saúde, sarar (Just., D. 112, 1; Ael. Aristid. 33, 9 K.=51 p. 573 D.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:21</a>, 22b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:23</a>, 28; 6:56; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:9</a>; 14:9. Também do restabelecimento que ocorre quando a morte já sobreveio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:50</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> manter, preservar em bom estado (pap.; Did., Gen. 145, 1.—Theoph. Ant. 1, 12 [p. 84, 4]) <span class=\"greek\">τὶ</span> algo (Ath. 17, 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">τύπος</span> … <span class=\"greek\">σῴζεται</span>, R. 20 p. 73, 10 <span class=\"greek\">μνήμην</span> e <span class=\"greek\">αἴσθησιν</span>; Eunap., Vi. Soph. p. 107: <span class=\"greek\">θειασμός</span>) pass. <span class=\"greek\">τὴν</span> <span class=\"greek\">κλῆσιν</span> <span class=\"greek\">σῴζεσθαι</span> Hs 8, 11, 1.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓔ</span> pass. prosperar, florescer, passar bem (SibOr 5, 227) <span class=\"greek\">σῴζεσθαι</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> 1 Cl 37:5. Como fórmula de tratamento usada na despedida <span class=\"greek\">σῴζεσθε</span> adeus, permanecei com boa saúde B 21:9 (cf. TestAbr B 2 p. 106, 1 [Stone p. 60] <span class=\"greek\">σῶσόν</span> <span class=\"greek\">σε</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> salvar ou preservar de perigo ou destruição transcendente, salvar/preservar da morte eterna, do juízo e de tudo quanto possa conduzir a tal morte, por ex., o pecado, também em sentido positivo trazer salvação messiânica, conduzir à salvação (LXX; Herm. Wr. 13, 19 <span class=\"greek\">σῴζειν</span>=‘dotar de vida eterna’.—Da passagem para um estado de salvação e de vida superior: Cebes 3, 2; 4, 3; 14, 1. Oposto <span class=\"greek\">κολάζειν</span> Orig., C. Cels. 2, 38, 16).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> ativo <span class=\"greek\">τινά</span> alguém ou <span class=\"greek\">τὶ</span> algo.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. de Deus e Cristo: Deus (ApcEsdr 2:17 p. 26, 9 Tdf. <span class=\"greek\">σὺ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">θέλεις</span> <span class=\"greek\">σῴζεις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">θέλεις</span> <span class=\"greek\">ἀπολεῖς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:5</a>; AcPlCor 2:10, 16. O acus. é facilmente subentendido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:12</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σῴζων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:16</a> D.—Cristo (Orig., C. Cels. 3, 14, 9): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:18</a> (<span class=\"greek\">εἰς</span> 10d); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:25</a>; MPol 9:3. <span class=\"greek\">σώσει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λαὸν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:21</a> (<span class=\"greek\">ς</span>. <span class=\"greek\">ἀπό</span> como Jos., Ant. 4, 128); também <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">αὐτῶν</span> GJs 11:3; cf. 14:2. Deve-se subentender o acus. 2 Cl 1:7. <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγνῶν</span> <span class=\"greek\">ἀνδρῶν</span> AcPl Ha 1, 16.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. de pessoas que são mediadoras da salvação divina: apóstolos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:16b</a>. O cônjuge crente num casamento misto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:16a</a>b (JJeremias, Die missionarische Aufgabe in der Mischehe, Bultmann Festschr. ’54, 255–60). De um cristão em relação a outro <span class=\"greek\">σώσει</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θανάτου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:20</a> (sobre <span class=\"greek\">ς</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">θαν</span>. v. 1a acima). Cf. Jd 23. Da segurança pessoal última <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:16a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:35b</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:24b</a> (quanto a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:35a</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:24a</a> v. 1a acima).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. de qualidades etc. que conduzem à salvação <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">σου</span> <span class=\"greek\">σέσωκέν</span> <span class=\"greek\">σε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:50</a> (v. 1c acima). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:21</a>; 2:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:21</a>; Hv 2, 3, 2. <span class=\"greek\">οὐ</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">π</span>[<span class=\"greek\">λοῦτος</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">βίῳ</span> <span class=\"greek\">λαμπ</span>]<span class=\"greek\">ρ̣ὰ</span> <span class=\"greek\">σώσι</span> (=<span class=\"greek\">σώσει</span>) <span class=\"greek\">σε</span> não é [a riqueza ou a pompa nesta vida] que te salvará AcPl Ha 9, 8 (quanto à restauração do texto, v. expressões correspondentes 2, 21–27).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> pass. ser salvo, alcançar salvação (TestAbr A 11 p. 90, 3 [Stone p. 28] al.; Just., A I, 18, 8 al.; Theoph. Ant. 2, 14 [p. 136, 15]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:22</a>; 19:25; 24:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:26</a>; 13:13; 16:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:12</a>; 18:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:34</a>; 10:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:21</a> (Jo 3:5); 15:1; 16:30f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:9</a>, 13 (Jo 3:5); 11:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:5</a>; 10:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:4</a> (JTurmel, Rev. d’Hist. et de Littérature religieuses 5, 1900, 385–415); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:18</a> (Pr 11:31); 2 Cl 4:2; 13:1; IPhld 5:2; Hs 9, 26, 6; AcPl Ha 1, 5 e 21.—<span class=\"greek\">σωθῆναι</span> <span class=\"greek\">διά</span> <span class=\"greek\">τινος</span> por meio de alguém (Ctesias: 688 Fgm. 8a p. 452 Jac. [em Ps.-Demetr., Eloc. c. 213] <span class=\"greek\">σὺ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">ἐσώθης</span>, <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">δέ</span>; Herm. Wr. 1, 26b <span class=\"greek\">ὅπως</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">γένος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀνθρωπότητος</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σωθῇ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:17</a>; 2 Cl 3:3; por meio de algo (Mel., P. 60, 440 <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἵματος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:15</a> (<span class=\"greek\">διά</span> A 3c); Hv 3, 3, 5; 3, 8, 3 (aqui a fé aparece como pessoa, mas permanece ainda como qualidade salvífica); 4, 2, 4. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> em ou por meio de alguém 1 Cl 38:1; AcPl Ha 2, 29; em ou por meio de algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:12</a>; 11:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:10</a>. <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> por alguém (Herm. Wr. 9, 5 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ς</span>.; Philo, Leg. All. 2, 101 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σῴζεται</span>) 2 Cl 8:2. <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> salvar-se afastando-se de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:40</a> (sobre <span class=\"greek\">ς</span>. <span class=\"greek\">ἀπό</span> v. 2a<span class=\"greek\">α</span> acima; ELövestam, ASTI 12, ’83, 84–92). <span class=\"greek\">διά</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> por meio de alguém, de algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:9</a>.—<span class=\"greek\">χάριτι</span> pela graça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:5</a>; Pol 1:3. <span class=\"greek\">τῇ</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:8</a>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐλπίδι</span> <span class=\"greek\">ἐσώθημεν</span> (somente) em esperança fomos (até agora) salvos ou é no contexto desta esperança que fomos salvos (isto é, o que há de vir culmina o que é realidade agora) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:24</a>.—<span class=\"greek\">οἱ</span> <span class=\"greek\">σῳζόμενοι</span> os que hão de ser ou estão sendo salvos (Iren. 1, 3, 5 [Harv. I 30, 9]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:47</a> (BMeyer, CBQ 27, ’65, 37f: cf. Is 37:2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:15</a> (oposto <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀπολλύμενοι</span> nas duas últimas passagens); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:24</a> t.r. (leitura erasmiana); 1 Cl 58:2; MPol 17:2.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> Certas passagens pertencem simultaneamente a 1 e 2. Incluem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:35</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:24</a> (v. 1a e 2a <span class=\"greek\">β</span> acima) e Lk 9:[56] v.l., onde <span class=\"greek\">σῴζειν</span> é usado em contraste com a destruição pelo fogo do céu, mas denota também a concessão de salvação transcendente (cf. Cornutus 16 p. 21, 9f <span class=\"greek\">οὐ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βλάπτειν</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῴζειν</span> <span class=\"greek\">γέγονεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> [=<span class=\"greek\">Ἑρμῆς</span>]). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:27</a> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπόλειμμα</span> <span class=\"greek\">σωθήσεται</span> (Is 10:22) o remanescente que há de escapar da morte é interpretado como a minoria que há de receber a salvação messiânica. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:15</a> escapar de uma casa em chamas é um símbolo de alcançar a salvação eterna (<span class=\"greek\">πῦρ</span> a; cf. também Cebes 3, 4 <span class=\"greek\">ἐὰν</span> <span class=\"greek\">δέ</span> <span class=\"greek\">τις</span> <span class=\"greek\">γνῷ</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀφροσύνη</span> <span class=\"greek\">ἀπόλλυται</span>, <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">σῷζεται</span>).—WWagner, Über <span class=\"greek\">σώζειν</span> u. seine Derivata im NT: ZNW 6, 1905, 205–35; J-BColon, La conception du Salut d’après les Év. Syn.: RSR 10, 1930, 1–39; 189–217; 370–415; 11, ’31, 27–70; 193–223; 382–412; JSevenster, Het verlossingsbegrip bij Philo. Vergeleken met de verlossingsgedachten van de Syn. evangeliën ’36; PMinear, And Great Shall be your Reward ’41; MGoguel, Les fondements de l’assurance du salut chez l’ap. Paul: RHPR 17, ’38, 105–44; BHHW II 995, 1068.—B. 752. DELG s.v. <span class=\"greek\">σῶς</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σωκράτης, ους, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σωκράτης</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">ὁ</span> Sócrates, nome encontrado frequentemente; um cristão de Corinto, que fez uma cópia do MPol: 22:2. EpilMosq 5 dá seu nome como <span class=\"greek\">Ἰσοκράτης</span>.—DELG s.v. <span class=\"greek\">σῶς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σῶμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σῶμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Hom.+) ‘corpo’.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> corpo de um ser humano ou animal, corpo</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> corpo morto, cadáver (assim sempre em Hom. [mas v. HHerter, <span class=\"greek\">σῶμα</span> bei Homer: Charites, Studien zur Altertumswissenschaft, ELanglotz Festschr., ed. KvonSchauenburg ’57, 206–17] e frequentemente mais tarde, por ex. Memnon: 434 Fgm. 1, 3, 3 Jac. <span class=\"greek\">καίειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>.=queimar o cadáver; inscr., pap., LXX; PsSol 2:27; TestJob 52:11; ApcMos 34 al.; Philo, Abr. 258; Jos., Bell. 6, 276, Ant. 18, 236; Ar. 4, 3; Mel., P. 28, 196) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:12</a> v.l.; 27:59; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:45</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:40</a>; GPt 2:4; pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:31</a>. Com gen. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:58</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:52</a>, 55; 24:3, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:38a</a>b, 40; 20:12; Jd 9; GPt 2:3. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:52</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:11</a>. AcPlCor 2:27.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> o corpo vivo (Hes. et al.) de animais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:3</a>.—Principalmente de seres humanos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:29f</a>; 6:22f; 26:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:29</a>; 14:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:34a</a>bc; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:18a</a>b; IRo 5:3. <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> as partes do corpo 4:2. De mulheres <span class=\"greek\">αἱ</span> <span class=\"greek\">ἀσθενεῖς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span> 1 Cl 6:2; cf. Hv 3, 11, 4.—Com <span class=\"greek\">πνεῦμα</span> e em contraste com ele (4 Macc 11:11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:10</a>, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:3</a>; 7:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:26</a>. Com <span class=\"greek\">ψυχή</span> e em contraste com ela (Pla., Gorg. 47, 493a; Diod S 34 + 35 Fgm. 2, 30; Appian, Bell. Civ. 5, 112 §467; Ael. Aristid. 45, 17f K.=8 p. 88f D.; Lucian, Imag. 23; PGM 7, 589; Wsd 1:4; 8:19f; 2 Macc 7:37; 14:38; 4 Macc 1:28; ApcEsdr 7:3 p. 32, 13 Tdf.; EpArist 139; Philo; Jos., Bell. 3, 372–78; 6, 55; Just., A I, 8, 4; D. 6, 2 al.; Tat. 13, 1; Ath. 1, 4; Did., Gen. 56, 4; Theoph. Ant. 1, 5 [p. 66, 2]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:25a</a>b; 10:28ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:4</a> v.l., 22f; 2 Cl 5:4 (um dito de Jesus, de fonte desconhecida); 12:4; MPol 14:2; AcPl Ha 1, 4. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> (v. o papiro cristão POxy 1161, 6 [IV d.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:23</a>. Com suas partes e em contraste com elas (ApcSed 11:13; Mel., P. 78, 563) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:12a</a>bc (Ltzm. ad loc.), 14–20 (PMich 149, 4, 26 [II d.C.] <span class=\"greek\">ἧπαρ</span> … <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:6</a>; 1 Cl 37:5abcd. O corpo como sede da função sexual <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:4a</a>b (direitos sobre o <span class=\"greek\">σῶμα</span> do próprio cônjuge, como Artem. 1, 44 p. 42, 14f; Iren. 1, 13, 3 [Harv. I 119, 10]).—O corpo como sede da vida mortal <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σώματι</span> estar no corpo = vivo, sujeito aos males da condição mortal (TestAbr A 9 p. 87, 3 [Stone p. 22]; Poryphr., Abst. 1, 38) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:3</a>. <span class=\"greek\">ἐνδημεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:6</a> (v. <span class=\"greek\">ἐνδημέω</span>). <span class=\"greek\">ἐκδημῆσαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> v. 8 (v. <span class=\"greek\">ἐκδημέω</span>). <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> durante o tempo da vida mortal de alguém (cf. Lucian, Menipp. 11, final, Catapl. 23) v. 10 (v. <span class=\"greek\">κομίζω</span> 3, mas v. também abaixo nesta seção). Paulo não sabe se, num momento de êxtase religioso, estava <span class=\"greek\">ἐν</span> <span class=\"greek\">σώματι</span> ou <span class=\"greek\">ἐκτὸς</span> (<span class=\"greek\">χωρὶς</span>) <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> 12:2f (de Epimênides [A2: Vorsokrat.5 I p. 29] dizia-se <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐξίοι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">ὁπόσον</span> <span class=\"greek\">ἤθελε</span> <span class=\"greek\">καιρὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">εἰσῄει</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span>; Clearchus, Fgm. 7: <span class=\"greek\">καθάπερ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Κλέαρχος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὕπνου</span> <span class=\"greek\">φησίν</span>, <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>, <span class=\"greek\">ὡς</span> <span class=\"greek\">ἄρα</span> <span class=\"greek\">χωρίζεται</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">εἴσεισιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">χρῆται</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">οἷον</span> <span class=\"greek\">καταγωγίῳ</span> [um lugar de repouso]. Em Fgm. 8 Clearco conta acerca de Cleônimo, o ateniense, que parecia morto, mas despertou após 3 dias e então relatou tudo quanto vira e ouvira <span class=\"greek\">ἐπειδὴ</span> <span class=\"greek\">χωρὶς</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>. Diz-se que sua alma finalmente chegou <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> <span class=\"greek\">χῶρον</span> <span class=\"greek\">ἱερὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἑστίας</span>; Maximus Tyr. 38, 3a–f <span class=\"greek\">Ἀριστέας</span> <span class=\"greek\">ἔφασκεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">καταλιποῦσαν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> a fim de percorrer o universo. Encontra crédito por toda parte. Semelhantemente 10, 2f. V. também a história de Hermótimo em Apollon. Paradox. 3, assim como Lucian, Musc. Enc. [A Mosca] 7.—Sobre os dois tipos de visão transcendente [com ou sem o corpo] v. Proclus, In Pla. Rem Publ. II p. 121, 26ff Kroll: <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τοιούτων</span> [como <span class=\"greek\">Ἐμπεδότιμος</span>] <span class=\"greek\">ἵστορες</span> [=testemunhas oculares], <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἄνευ</span> <span class=\"greek\">σώματος</span> [como <span class=\"greek\">Κλεώνυμος</span>]. <span class=\"greek\">καὶ</span> <span class=\"greek\">πλήρεις</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">παραδόσεις</span> <span class=\"greek\">τούτων</span>.). <span class=\"greek\">ἀπὼν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span> (<span class=\"greek\">παρὼν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:3</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">παρουσία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:10</a> (<span class=\"greek\">παρουσία</span> 1). O corpo é o instrumento da experiência e do sofrimento humanos 4:10ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:17</a> (alusão AcPlCor 2, 35); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:20</a>; o corpo é o órgão da atividade de uma pessoa: <span class=\"greek\">δοξάσατε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">ὑμῶν</span> glorificai a Deus por meio de vosso corpo, isto é, levando uma vida reta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:20</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:1</a>. Talvez caiba aqui (v. acima nesta seção) <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:10</a> que, nesse caso, seria tomado em sentido instrumental, com ou por meio do corpo (cf. Pla., Phd. 65a; Ps.-Pla., Axioch. 13, 371c; Aelian, NA 5, 26 <span class=\"greek\">τὰ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">πραττόμενα</span>). Em algumas das últimas passagens mencionadas (tais como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:20</a>; também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:28</a> com paralelo em Plut., Mor. 142e: v. HAlmqvist, Plut. u. d. NT ’46, 116f) o corpo é quase sinônimo da personalidade inteira (como Aeschin., Or. 2, 58; X., An. 1, 9, 12 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">σώματα</span>=eles mesmos. Appian, Syr. 41 §218 <span class=\"greek\">παρεδίδου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐθέλουσιν</span> <span class=\"greek\">ἀπαγαγεῖν</span>=[Epaminondas] entregou-se àqueles que desejavam levá-lo, Mithr. 27 §107 <span class=\"greek\">ἐς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">αὐτοῦ</span>=contra sua pessoa, Bell. Civ. 2, 106 §442 a pessoa de César [<span class=\"greek\">σῶμα</span>] é <span class=\"greek\">ἱερὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄσυλος</span>=sagrada e inviolável; 3, 39 §157 <span class=\"greek\">ἔργον</span> … <span class=\"greek\">σῶμα</span>=curso de ação … pessoa; Mitt-Wilck. I/2, 55, 7 [III a.C.] <span class=\"greek\">ἑκάστου</span> <span class=\"greek\">σώματος</span>=para cada pessoa. V. a nota de Wilcken).—Por estar sujeito ao pecado e à morte, o corpo mortal do homem como <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> (<span class=\"greek\">σάρξ</span> 2c<span class=\"greek\">α</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:11</a> é um <span class=\"greek\">σῶμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁμαρτίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:6</a> ou <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> 7:24; cf. 8:11. De fato, <span class=\"greek\">σῶμα</span> pode efetivamente ocupar o lugar de <span class=\"greek\">σάρξ</span> 8:13 (cf. Herm. Wr. 4, 6b <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">μισήσῃς</span>, <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">φιλῆσαι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δύνασαι</span>; 11, 21a.—Cf. Hippol., Ref. 5, 19, 6). Como <span class=\"greek\">σῶμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ταπεινώσεως</span> corpo humilde, contrasta com o <span class=\"greek\">σῶμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> corpo glorioso dos seres celestiais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:21</a>. Em outra passagem <span class=\"greek\">σῶμα</span> <span class=\"greek\">ψυχικόν</span> dos mortais opõe-se ao <span class=\"greek\">σῶμα</span> <span class=\"greek\">πνευματικόν</span> após a ressurreição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.44\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:44a</a>bc.—O corpo terreno de Cristo, que estava sujeito à morte (Orig., C. Cels. 2, 9, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:5</a> (Ps 39:7 v.l.), 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:24</a>; AcPlCor 2:16f. <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀστᾶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">Χριστοῦ</span> 2:32. <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:22</a>. Especialmente na linguagem da Eucaristia (oposto <span class=\"greek\">αἷμα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:16</a> (GBornkamm, NTS 2, ’56, 202–6); 11:24, 27, 29. V. a literatura s.v. <span class=\"greek\">ἀγάπη</span> 2 e <span class=\"greek\">εὐχαριστία</span> 3, também JBonsirven, Biblica 29, ’48, 205–19.—<span class=\"greek\">ἓν</span> <span class=\"greek\">σῶμα</span> um só corpo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:16</a> (cf. Jos., Ant. 7, 66 <span class=\"greek\">Δαυίδης</span> <span class=\"greek\">τήν</span> <span class=\"greek\">τε</span> <span class=\"greek\">ἄνω</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἄκραν</span> <span class=\"greek\">συνάψας</span> <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ἕν</span> <span class=\"greek\">σῶμα</span>; Artem. 3, 66 p. 196, 9; RKempthorne, NTS 14. ’67/68, 568–74).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> pl. <span class=\"greek\">σώματα</span> escravos (Herodas 2, 87 <span class=\"greek\">δοῦλα</span> <span class=\"greek\">σώματα</span>; Polyb. et al.; frequentemente Vett. Val.; inscr., pap.; Gen 36:6; Tob 10:10; Bel 32; 2 Macc 8:11; Jos., Ant. 14, 321; cf. nosso coloquial ‘arranje alguns corpos para o trabalho’) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:13</a> (cf. Ezk 27:13; o uso absoluto rejeitado pelos aticistas, v. Phryn. 378 Lob.).</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> estrutura de planta e semente, corpo. A fim de obter resposta à sua própria pergunta em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:35</a> <span class=\"greek\">ποίῳ</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">ἔρχονται</span>; (isto é, os mortos após a ressurreição), Paulo fala de corpos de plantas (que diferem em espécie do ‘corpo’ da semente que é plantada.—Maximus Tyr. 40, 60e distingue entre os <span class=\"greek\">σώματα</span> das plantas, que envelhecem e perecem, e seus <span class=\"greek\">σπέρματα</span>, que perduram.—<span class=\"greek\">σώματα</span> de plantas também em Apollon. Paradox. 7 [segundo Aristot.]) v. 37f, e de <span class=\"greek\">σώματα</span> <span class=\"greek\">ἐπουράνια</span> dos corpos celestes v. 40 (cf. Ps.-Aristot., De Mundo 2, 2 os astros como <span class=\"greek\">σώματα</span> <span class=\"greek\">θεῖα</span>; Maximus Tyr. 21, 8b <span class=\"greek\">οὐρανὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">σώματα</span>, segundo 11, 12a <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀστέρες</span>; 40, 4h; Sallust. 9 p. 18, 5).</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> realidade substancial, a própria coisa, a realidade na imagem de um corpo que projeta sombra, em contraste com <span class=\"greek\">σκιά</span> (q.v. 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:17</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">⑤</span> um grupo unificado de pessoas, corpo, extensão fig. de 1, da comunidade cristã ou igreja (cf. Cyr. Ins. 58, ‘corpo dos helenos’; Polyaenus, Exc. 18, 4 da falange; Libanius, Or. 1 p. 176, 25 F. <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> <span class=\"greek\">ς</span>.; Plut., Philop. 360 [8, 2]), especialmente como o corpo de Cristo, que ele preenche ou vivifica como seu Espírito (neste caso a cabeça pertence ao corpo, como Appian, Bell. Civ. 3, 26 §101, onde uma cabeça decepada é distinguida de <span class=\"greek\">τὸ</span> <span class=\"greek\">ἄλλο</span> <span class=\"greek\">σῶμα</span>=o restante do corpo), ou coroa como sua Cabeça (Hdt. 7, 140; Quint. Smyrn. 11, 58; SIG 1169, 3; 15 <span class=\"greek\">κεφαλή</span> com <span class=\"greek\">σῶμα</span> como algo igualmente independente; Orig., C. Cels. 6, 79, 27): <span class=\"greek\">οἱ</span> <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">σῶμά</span> <span class=\"greek\">ἐσμεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:5</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:17</a>; 12:13, 27; Eph (v. Schlier s.v. <span class=\"greek\">ἐκκλησία</span> 3c) 1:23; 2:16; 4:12, 16; 5:23, 30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:18</a>, 24; 2:19; 3:15; ISm 1:2; Hs 9, 17, 5; 9, 18, 3f. <span class=\"greek\">ἓν</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">πνεῦμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:4</a>; cf. Hs 9, 13, 5; 7 (Iambl., Vi. Pyth. 30, 167: todos como <span class=\"greek\">ἓν</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μία</span> <span class=\"greek\">ψυχή</span>; também Just., D. 42, 3) <span class=\"greek\">διέλκομεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">στασιάζομεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> 1 Cl 46:7.—T Schmidt, Der Leib Christi (<span class=\"greek\">σῶμα</span> <span class=\"greek\">Χριστοῦ</span>) 1919; EKäsemann, Leib u. Leib Christi ’33 (para uma crítica v. SHanson, Unity of the Church in the NT ’46, 113–16); ÉMersch, Le Corps mystique du Christ2 ’36; AWikenhauser, D. Kirche als d. myst. Leib Christi, nach dem Ap. Pls2 ’40; EPercy, D. Leib Christi in d. paulin. Homologumena u. Antilegomena ’42; RHirzel, Die Person: SBMünAk 1914 H. 10 p. 6–28 (história semântica de <span class=\"greek\">σῶμα</span>); WKnox, Parallels to the NT use of <span class=\"greek\">σῶμα</span>: JTS 39, ’38, 243–46; FDillistone, How Is the Church Christ’s Body?: Theology Today 2, ’45/46, 56–68; WGoossens, L’Église corps de Christ d’après St. Paul2 ’49; CCraig, Soma Christou: The Joy of Study ’51, 73–85; JRobinson, The Body: A Study in Pauline Theol. ’52; RBultmann, Theol. of the NT, trad. KGrobel ’51, 192–203; HClavier, CHDodd Festschr. ’56, 342–62; CColpe, Zur Leib-Christi Vorstellung im Eph, ’60, 172–87; KGrobel, Bultmann Festschr. ’54, 52–59; HHegermann, TLZ 85, ’60, 839–42; ESchweizer, ibid. 86, ’61, 161–74; 241–56; JMeuzelaar, D. Leib des Messias, ’61; MDahl, The Resurrection of the Body, ’62; RJewett, Paul’s Anthropological Terms, ’71, 201–304; JZiegler, NovT 25, ’83, 133–45 (LXX); JDunn: JSNT Suppl. 100, ’94, 163–81 (Col.).—B. 198. New Docs 4, 38f. DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σωματεῖον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σωματεῖον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">σῶμα</span>; de resto somente POxy 5 recto,10f; Codex Iustin. 6, 48, 1, 10, Basilica 2, 5, 24) modo de funcionar como grupo, vida corporativa ISm 11:2 (v.l. <span class=\"greek\">σωμάτιον</span>). Talvez neste caso tenhamos uma grafia itacística errônea comum de <span class=\"greek\">σωμάτιον</span> (q.v.).—DELG s.v. <span class=\"greek\">σῶμα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σωματικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σωματικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">σῶμα</span>; Aristot. et al.; inscr., pap., 4 Macc; Ath. R. 18 p. 70, 32 al.)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> relativo ao que é corpóreo em oposição ao incorpóreo, corporal, corpóreo, <span class=\"greek\">σωματικῷ</span> (oposto <span class=\"greek\">ἀσώματος</span> Ps.-Pla., Tim. Locr. 96a; Philo, Op. M. 16; 18) <span class=\"greek\">εἴδει</span> forma corporal, isto é, o Espírito Santo desceu em alguma espécie de forma física: <span class=\"greek\">ὡς</span> <span class=\"greek\">περιστεράν</span> ‘como uma pomba’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:22</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo ao corpo físico, referente ao corpo, corporal (Aristot. et al.; Herm. Wr. 1, 1; inscr., pap., Philo; Jos., Bell. 1, 430; 6, 55 <span class=\"greek\">ς</span>. <span class=\"greek\">ἕξις</span>) <span class=\"greek\">ἡ</span> <span class=\"greek\">σωματικὴ</span> <span class=\"greek\">γυμνασία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:8</a>. (<span class=\"greek\">σαρκικαὶ</span> <span class=\"greek\">καὶ</span>) <span class=\"greek\">σωματικαὶ</span> <span class=\"greek\">ἐπιθυμίαι</span> D 1:4 cód. (Aristot., EN 7, 7, 1149b, 26 <span class=\"greek\">ἐπιθυμίαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡδοναί</span>; 4 Macc 1:32; Ath., R. 18 p. 70, 32).—DELG s.v. <span class=\"greek\">σῶμα</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σωματικῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σωματικῶς</span> adv. de <span class=\"greek\">σωματικός</span> (Plut., Mor. 424d; Vett. Val. 231, 2; 269, 28; OGI 664, 17 [54 d.C.]; pap. [Sb 8748, 15–178 d.C.], outros New Docs 3, 86; TestAbr B 7 p. 112, 7 [Stone p. 72]; Philo, Rer. Div. Her. 84) corporalmente, corporeamente de Cristo <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">κατοικεῖ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θεότητος</span> <span class=\"greek\">σωματικῶς</span> nele habita corporalmente toda a plenitude da Divindade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:9</a> (provavelmente a compreender a partir de 2:17 [v. <span class=\"greek\">σῶμα</span> 4] como = na realidade, não figuradamente). <span class=\"greek\">σωματικῶς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ταυτησὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">ὑποστησομένης</span> quando o domínio de Cristo houver de ser estabelecido materialmente nesta terra Papias (2:12).—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σωμάτιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σωμάτιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Isocr. et al.; pap.) dim. de <span class=\"greek\">σῶμα</span>.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> pequeno corpo, especialmente pobre (pequeno) corpo (Socrat., Ep. 30, 1; 31; Epict. 1, 1, 10; 24; 1, 9, 2 al., v. o índice da edição de Schenkl; Lucian, Jupp. Trag. 41; Philo, Leg. ad Gai. 273) lit., do corpo torturado de um mártir MPol 17:1.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> um corpo transcendente, corpo, extensão fig. de 1, o ‘corpo’ de uma igreja perseguida ISm 11:2 v.l. (em lugar de <span class=\"greek\">σωματεῖον</span> ‘corpo corporativo’, a leitura do texto de Bihlmeyer; v. L-S-J-M e a nota de Lightfoot ad loc.).—DELG s.v. <span class=\"greek\">σῶμα</span>. M-M. s.v. <span class=\"greek\">σῶμα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σώπατρος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σώπατρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Athen.; Jos., Ant. 14, 241; inscr.) Sópatro, filho de Pirro. S. era cristão de Bereia e companheiro de Paulo em sua última viagem a Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:4</a>. O nome de seu pai falta em uma v.l., e outra dá o próprio nome como <span class=\"greek\">Σωσίπατρος</span> (q.v.).—Hemer, Acts 236.—LGPN I.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σωρεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σωρεύω</span> (<span class=\"greek\">σωρός</span> ‘montão’) fut. <span class=\"greek\">σωρεύσω</span>; aor. 3 sg. <span class=\"greek\">ἐσώρευσεν</span> Jdth 15:11; perf. pass. part. <span class=\"greek\">σεσωρευμένος</span> (Aristot. et al.; Cat. Cod. Astr. IX/2 p. 115, 9 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀήρ</span>; ApcSed 11:6, 8, 11 p. 134, 18, 22, e 26 Ja.; Philo, De Prov. em Eus., PE 8, 14, 62; Jos., Ant. 12, 211).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> acumular colocando uma coisa sobre outra, amontoar/empilhar (Polyb.; Diod S 5, 46, 5 et al.; Jos., Bell. 4, 380; 6, 431) <span class=\"greek\">τὶ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> algo sobre algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:20</a> (Pr 25:22; cf. <span class=\"greek\">ἄνθραξ</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> encher um lugar de montões de algo, sobrecarregar com (Polyb. 16, 8, 9; Maximus Tyr. 35, 3b; Herodian 4, 8, 9 <span class=\"greek\">βωμοὺς</span> <span class=\"greek\">λιβάνῳ</span>; 5, 5, 8) pass., fig. <span class=\"greek\">γυναικάρια</span> <span class=\"greek\">σεσωρευμένα</span> <span class=\"greek\">ἁμαρτίαις</span> mulheres insensatas, sobrecarregadas por seus pecados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:6</a>.—DELG s.v. <span class=\"greek\">σωρός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σωσθένης, ους, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σωσθένης</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">ὁ</span> (Diod S, Diog. L.; Achilles Tat. 5, 17, 5 al.; inscr., pap.; quanto à terminação-<span class=\"greek\">ης</span> v. Mussies 77) Sóstenes</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> dirigente de uma sinagoga em Corinto na época do primeiro trabalho missionário de Paulo naquela cidade. Foi espancado na presença do procônsul Gálio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:17</a>, mas o relato (18:12–17) não diz por quê. De Teodoreto a Zahn muitos estudiosos, não sem boa razão, identificaram-no com o seguinte.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> um ‘irmão’ mencionado na saudação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:1</a>, ao lado do próprio Paulo. V. também a subscrição. É conhecido dos coríntios, mas não precisa ter sido ele próprio coríntio, a menos que deva ser identificado com 1.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σωσίπατρος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σωσίπατρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Athen.; inscr., pap.; 2 Macc 12:19, 24) Sosípatro, designado como <span class=\"greek\">συγγενής</span> de Paulo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:21</a>, onde também envia saudações à igreja. É frequentemente considerado a mesma pessoa que Sópatro de Bereia (v. <span class=\"greek\">Σώπατρος</span>), por ex., por Zahn, Ltzm. Linguisticamente isto é provável.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σωτήρ, ῆρος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σωτήρ</span>, <span class=\"greek\">ῆρος</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">σῴζω</span>) aquele que resgata, salvador, libertador, preservador, como título de divindades Pind., Aeschyl.+; inscr., pap.; TestSol 17:4. Este era o epíteto especialmente de Asclépio, o deus da cura (Ael. Aristid. 42, 4 K. <span class=\"greek\">ς</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span>; OGI 332, 9 [138–133 a.C.], v. nota 8; SIG 1112, 2; 1148); Celso compara o culto de Ascl. com a adoração cristã do Salvador (Origen, C. Cels. 3, 3). Igualmente divindades das religiões de mistério, como Serápis e Ísis (<span class=\"greek\">Σαράπιδι</span> <span class=\"greek\">Ἴσιδι</span> <span class=\"greek\">Σωτῆρσι</span>: OGI 87; Sb 597 [ambos III a.C.]; Sb 169 [época ptolemaica]; 596; CIG 4930b [I a.C.]), assim como Héracles (<span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">ς</span>.: Dio Chrys. 1, 84) ou Zeus (Ael. Aristid. 52 p. 608 D.: <span class=\"greek\">Ζεὺς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ς</span>.).—GAnrich, Das antike Mysterienwesen 1894, 47ff; GWobbermin, Religionsgesch. Studien 1896, 105ff.—Na especulação gnóstica: <span class=\"greek\">ὁ</span> <span class=\"greek\">ς</span>. = <span class=\"greek\">ὁ</span> <span class=\"greek\">παράκλητος</span> Iren. 1, 4, 5 (Harv. I, 38, 9). A LXX tem <span class=\"greek\">σωτήρ</span> como termo para Deus; assim também ApcSed 13:6 p. 135, 29 Ja.; e assim também Fílon (v. MDibelius, Hdb., exc. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:10</a>) e SibOr 1, 73; 3, 35; mas <span class=\"greek\">ς</span>. não se encontra assim em EpArist, Test12Patr ou Josefo (v. ASchlatter, Wie sprach Jos. von Gott? 1910, 66).—Desde cedo <span class=\"greek\">σωτήρ</span> foi usado como título honorífico para pessoas merecedoras (v. X., Hell. 4, 4, 6, Ages. 11, 13; Plut., Arat. 53, 4; Herodian 3, 12, 2.—Ps.-Lucian, Ocyp. 78 numa alocução a um médico [v. <span class=\"greek\">θεός</span> 4a]; JosAs 25:6 [de José]; a mesma expressão IXanthos p. 45 no. 23, 3f, de Marco Agripa [I a.C.]; Jos., Vi. 244; 259 Josefo como <span class=\"greek\">εὐεργέτης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωτήρ</span> da Galileia), e em inscr. e pap. encontramo-lo predicado de altos funcionários e de pessoas na vida privada. Isso nunca ocorre em nossa literatura. Mas fora de nossa literatura aplica-se a personalidades atuantes nos assuntos do mundo, a fim de retirá-las das fileiras da humanidade comum e colocá-las em posição significativamente superior. Por exemplo, Epicuro é chamado <span class=\"greek\">σωτήρ</span> por seus seguidores (Philod.: pap., Herc. 346, 4, 19 <span class=\"greek\">ὑμνεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σωτῆρα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἡμέτερον</span>.—ARW 18, 1930, 392–95; CJensen, Ein neuer Brief Epikurs: GGAbh. III/5, ’33, 80f). De importância muito maior é a designação do governante (divinizado) como <span class=\"greek\">ς</span>. (Ptolemeu I Sóter [323–285 a.C.] <span class=\"greek\">Πτολεμαῖος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Βερενίκη</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">Σωτῆρες</span>: APF 5, 1913, 156, 1; v. Sb 306 e frequentemente em épocas posteriores, também dos imperadores romanos [Philo, In Flacc. 74; 126, Leg. ad Gai. 22; cf. Jos., Bell. 3, 459]).—PWendland, <span class=\"greek\">Σωτήρ</span>: ZNW 5, 1904, 335ff; Magie 67f; HLietzmann, Der Weltheiland 1909; WOtto, Augustus Soter: Her 45, 1910, 448–60; FDölger, Ichthys 1910, 406–22; Dssm., LO 311f (LAE 368f); ELohmeyer, Christuskult u. Kaiserkult 1919; Bousset, Kyrios Christos2 1921, 241ff; EMeyer III 392ff; E-BAllo, Les dieux sauveurs du paganisme gréco-romain: RSPT 15, 1926, 5–34; KBornhausen, Der Erlöser 1927; HLinssen, <span class=\"greek\">Θεος</span> <span class=\"greek\">Σωτηρ</span>, diss. Bonn 1929=Jahrb. f. Liturgiewiss. 8, 1928, 1–75; AOxé, <span class=\"greek\">Σωτήρ</span> b. den Römern: WienerStud 48, 1930, 38–61; WStaerk, Soter, I ’33; II ’38. V. também GHerzog-Hauser, Soter … im altgriech. Epos ’31; ANock, s.v. <span class=\"greek\">εὐεργέτης</span>.—CColpe, Die Religionsgeschichtliche Schule ’61 (crítica de parte da literatura acima citada); FDanker, Benefactor ’82.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> de Deus <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σωτήρ</span> <span class=\"greek\">μου</span> (Ps 24:5; 26:9; Mi 7:7 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:47</a>. <span class=\"greek\">θεὸς</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:1</a>; Jd 25. <span class=\"greek\">ὁ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">θεός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:3</a>; 2:10; 3:4. <span class=\"greek\">ς</span>. <span class=\"greek\">πάντων</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">μάλιστα</span> <span class=\"greek\">πιστῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:10</a> (cf. PPetr III, 20 I, 15 [246 a.C.] <span class=\"greek\">πάντων</span> <span class=\"greek\">σωτῆρα</span> e v. acima Héracles como <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">ς</span>. e em b abaixo Serápis). <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀπηλπισμένων</span> <span class=\"greek\">σωτήρ</span> o Salvador dos desesperados 1 Cl 59:3.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> de Cristo (Just., A I, 33, 7 <span class=\"greek\">τὸ</span> … <span class=\"greek\">Ἰησοῦς</span> … <span class=\"greek\">σωτὴρ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Ἑλληνίδι</span> <span class=\"greek\">διαλέκτῳ</span> <span class=\"greek\">δηλοῖ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:20</a>; Dg 9:6; Ox 840, 12; 21 (restaurado); 30; GMary 463, linhas 4, 8, 18, 22, 31; Ox 1081, 27 (SJCh 90, 4); Qua. Com <span class=\"greek\">ἀρχηγός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:31</a>; 2 Cl 20:5 (<span class=\"greek\">ἀρχηγὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀφθαρσίας</span>). <span class=\"greek\">σωτὴρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> Salvador do corpo (isto é, de seu corpo, a comunidade cristã) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:23</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">σωτὴρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> (inscr.; cf. WWeber, Untersuchungen zur Gesch. des Kaisers Hadrianus 1907, 225f; 222) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:14</a>. <span class=\"greek\">ς</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> (Ael. Aristid. 45, 20 K.=8 p. 90 D. chama Serápis <span class=\"greek\">κηδεμόνα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωτῆρα</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">αὐτάρκη</span> <span class=\"greek\">θεόν</span>) GPt 4:13. <span class=\"greek\">ὁ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἰ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:10</a>; ISm 7:1; com <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἰ</span>. ou <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>. precedendo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:4</a>; 3:6; IEph 1:1; IMg inscr.; Pol inscr. <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἱ</span>. nosso grande Deus e Salvador Cristo Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:13</a> (cf. PLond III, 604b, 118 p. 80 [47 d.C.] <span class=\"greek\">τῷ</span> <span class=\"greek\">μεγάλῳ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">σωτῆρι</span>; mas a presença de <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:13</a> sugere aspecto semântico diferente e pode justificar a tradução na margem da NRSV). V. MDibelius, exc. após <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:14</a>; HWindisch, Z. Christologie der Past.: ZNW 34, ’35, 213–38.—<span class=\"greek\">ὁ</span> <span class=\"greek\">σωτὴρ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>. IPhld 9:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ψυχῶν</span> MPol 19:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:1</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> (<span class=\"greek\">ἡμῶν</span>) <span class=\"greek\">καὶ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>. v. 11; 2:20; 3:18; sem nome algum (assim <span class=\"greek\">ὁ</span> <span class=\"greek\">σωτήρ</span> [significando Asclépio] Ael. Aristid. 47, 1 K.=23 p. 445 D.; 66 K.=p. 462 D.; 48, 7 K.=24 p. 466 D.—Orig., C. Cels. 6, 64, 16; Hippol., Ref. 5, 8, 27) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:2</a>; AcPl Ha 8, 29 (restaurado: <span class=\"greek\">καὶ</span> <span class=\"greek\">σωτῆρα</span>). V. Loewe s.v. <span class=\"greek\">σωτηρία</span>, final.—Pauly-W. 2, VI 1211–21; Kl. Pauly V 289; RAC VI 54–219; DLNT 1082–84; BHHW I 430–32.—M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σωτηρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σωτηρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Trag., Hdt.+)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> libertação, preservação, com ênfase no aspecto físico: da morte iminente, especialmente no mar (IMaronIsis 11; Diod S 3, 40, 1 <span class=\"greek\">λιμὴν</span> <span class=\"greek\">σωτηρίας</span>; 2 Macc 3:32; GrBar 1:3; Philo, Mos. 1, 317; Jos., Ant. 7, 5; 183; Ar. 3, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:7</a>. Da libertação dos israelitas da servidão egípcia (Jos., Ant. 2, 331) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:25</a> (<span class=\"greek\">διδόναι</span> <span class=\"greek\">σωτηρίαν</span> por parte de uma divindade: Menand., Col. Fgm. 292, 5=1, 5 Kö.). Sobrevivência de uma mão castigada pelo fogo GJs 20:3. Uma transição para a acepção 2 encontra-se em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.71\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:71</a>, onde se espera <span class=\"greek\">σωτηρία</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐχθρῶν</span> <span class=\"greek\">ἡμῶν</span> libertação da mão de nossos inimigos (cf. Ps 105:10 e ApcPt Rainer <span class=\"greek\">ἐν</span> <span class=\"greek\">σωτηρίᾳ</span> <span class=\"greek\">Ἀχερουσίας</span> <span class=\"greek\">λίμνης</span>, onde a referência é a um batismo que marca o início da vida no Elísio); 1 Cl 39:9 (Job 5:4).—V. <span class=\"greek\">λίμνη</span>, final.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> salvação, com ênfase nos aspectos transcendentes (LXX, Just., Iren; cf. Herm. Wr. 7, 2 [sobre a salvação por meio da gnose v. GLuck, SBLSP 24, ’85, 315–20]; Ael. Aristid., Sacr. Serm. 3, 46 p. 424 Keil <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἴσιδος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἕτερα</span> <span class=\"greek\">ἀμύθητα</span> <span class=\"greek\">φέροντα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σωτηρίαν</span>; o Hino a Átis em Firmicus Maternus, De Errore Prof. Relig. 22, 1 <span class=\"greek\">Θαρρεῖτε</span> <span class=\"greek\">μύσται</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σεσωσμένου</span>. <span class=\"greek\">Ἔσται</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πόνων</span> <span class=\"greek\">σωτηρία</span> [HHepding, Attis, seine Mythen u. sein Kult 1903, 167]. O lat. ‘salus’ na descrição da cerimônia de Ísis em Apuleio corresponde ao gr. <span class=\"greek\">σωτηρία</span> [GAnrich, Das antike Mysterienwesen 1894, 47f; Rtzst., Mysterienrel.3 39]). Em nossa literatura este sentido encontra-se somente em conexão com Jesus Cristo como Salvador. Essa salvação se faz conhecer e sentir no presente, mas será plenamente revelada no futuro. Oposto <span class=\"greek\">ἀπώλεια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:28</a> (Mel., P. 49, 356; sobre a probabilidade de metáfora militar v. EKrentz, em Origins and Method, JHurd Festschr., ed. BMcLean, ’93, 125f); <span class=\"greek\">θάνατος</span> (cf. Damasc., Vi. Isid. 131: por meio de Átis e da Mãe dos Deuses vem <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ᾅδου</span> <span class=\"greek\">γεγονυῖα</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">σωτ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:10</a>; <span class=\"greek\">ὀργή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:9</a>. Com <span class=\"greek\">ζωή</span> 2 Cl 19:1; <span class=\"greek\">ζωὴ</span> <span class=\"greek\">αἰώνιος</span> IEph 18:1. <span class=\"greek\">σωτηρία</span> <span class=\"greek\">αἰώνιος</span> (Is 45:17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:9</a>; final breve de Mk; <span class=\"greek\">ἣ</span> <span class=\"greek\">κοινὴ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">σωτ</span>. Jd 3 (SIG 409, 33f <span class=\"greek\">ἀγωνιζόμενος</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κοινῆς</span> <span class=\"greek\">σωτηρίας</span>); <span class=\"greek\">σωτ</span>. <span class=\"greek\">ψυχῶν</span> salvação de almas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:9</a> (<span class=\"greek\">ς</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ψυχῶν</span> Hippol., Ref. 10, 19, 3); cf. v. 10 (ESelwyn, 1 Pt ’46, 252f). <span class=\"greek\">σωτηρία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐκλεκτῶν</span> MPol 22:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σῳζομένων</span> <span class=\"greek\">σωτ</span>. 17:2 (<span class=\"greek\">ἡ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">μετανοούντων</span> Did., Gen. 71, 28; <span class=\"greek\">σωτηρία</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγαθῶν</span> Hippol., Ref. 7, 28, 6; <span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">ς</span>. Orig., C. Cels. 4, 73, 13). Sobre <span class=\"greek\">κέρας</span> <span class=\"greek\">σωτηρίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.69\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:69</a> v. <span class=\"greek\">κέρας</span> 3. <span class=\"greek\">σωτηρίας</span> como gen. objetivo dependente de vários substantivos: <span class=\"greek\">γνῶσις</span> <span class=\"greek\">σωτηρίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.77\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:77</a>; <span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">σωτ</span>. (TestJob 24:1; cf. Philemo Com. 181 <span class=\"greek\">οἱ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">σέβοντες</span> <span class=\"greek\">ἐλπίδας</span> <span class=\"greek\">καλὰς</span> <span class=\"greek\">ἔχουσιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σωτηρίαν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:8</a>; 2 Cl 1:7; <span class=\"greek\">ἔνδειξις</span> <span class=\"greek\">σωτ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:28</a> (oposto <span class=\"greek\">ἀπώλεια</span>). <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτηρίας</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:13</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτηρίας</span> <span class=\"greek\">ταύτης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:26</a>. <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">σωτηρίας</span> caminho para a salvação 16:17; <span class=\"greek\">περιποίησις</span> <span class=\"greek\">σωτ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:9</a>. <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">σωτηρίας</span> (citação de Is 49:8) do dia em que o apóstolo os chama à salvação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:2a</a>b (cf. o mistério em Apuleius, Metam. 11, 5 ‘dies salutaris’ = ‘dia da iniciação’). Cristo é <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀρχηγὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:10</a> (<span class=\"greek\">ἀρχηγός</span> 3). <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτ</span>. <span class=\"greek\">μου</span> 1 Cl 18:14 (Ps 50:16).—Usado com verbos: <span class=\"greek\">ἔχειν</span> <span class=\"greek\">σωτηρίαν</span> Hv 2, 2, 5; 3, 6, 1; m 10, 2, 4; 12, 3, 6. <span class=\"greek\">κληρονομεῖν</span> <span class=\"greek\">σωτηρίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:14</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">σωτ</span>. <span class=\"greek\">κατεργάζεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:12</a> (<span class=\"greek\">κατεργάζομαι</span> 2). <span class=\"greek\">σωτηρίας</span> <span class=\"greek\">τυχεῖν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">Ἰ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:10</a> (<span class=\"greek\">τυχεῖν</span> <span class=\"greek\">σωτηρίας</span>: Diod S 11, 4, 4; 11, 9, 1). <span class=\"greek\">εἰς</span> <span class=\"greek\">σωτηρίαν</span> para salvação (isto é, apropriar-se dela ou concedê-la a outrem) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:16</a>; 10:1, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:19</a> (<span class=\"greek\">ἀποβαίνω</span> 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:2</a>. <span class=\"greek\">πόρρω</span> … <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτ</span>. 1Cl 39:9 (Job 3:4). <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀνήκοντα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σωτηρίαν</span> as coisas que dizem respeito à salvação 1 Cl 45:1; B 17:1 (cf. SIG 1157, 12f).—Espera-se claramente que <span class=\"greek\">σωτηρία</span> chegue à plena culminação com a segunda vinda do Senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:5</a>.—(<span class=\"greek\">ἡ</span>) <span class=\"greek\">σωτηρία</span> sem outra qualificação=salvação encontra-se também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:9</a> (cf. GJs 19:2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:22</a> (<span class=\"greek\">ἡ</span> <span class=\"greek\">σωτ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span> <span class=\"greek\">ἐστίν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:12</a> (cf. Jos., Ant. 3, 23 <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σωτηρίαν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἄλλῳ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:3</a> (<span class=\"greek\">τηλικαύτη</span> <span class=\"greek\">σωτ</span>.); 6:9. <span class=\"greek\">ἡ</span> <span class=\"greek\">σωτ</span>. <span class=\"greek\">ἡμῶν</span> 2 Cl 1:1; 17:5; B 2:10.—Cristo morreu até mesmo pela salvação dos ninivitas arrependidos no tempo de Jonas 1 Cl 7:7; cf. v. 4.—<span class=\"greek\">σωτηρία</span> está por metonímia em lugar de <span class=\"greek\">σωτήρ</span> (na citação de Is 49:6) <span class=\"greek\">τοῦ</span> <span class=\"greek\">εἶναί</span> <span class=\"greek\">σε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σωτηρίαν</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">ἐσχάτου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:47</a>; B 14:8. Por outro lado, designando uma circunstância favorável à nossa obtenção da salvação <span class=\"greek\">ἡγεῖσθαί</span> <span class=\"greek\">τι</span> <span class=\"greek\">σωτηρίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:15</a>.—Nas três passagens de Rv em que <span class=\"greek\">σωτ</span>. aparece como parte de uma doxologia temos um hebraísmo (salvação como vitória intimamente associada a Deus; PEllingworth, BT 34, ’83, 444f; cf. Ps 3:9 e PsSol 10:8 <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σωτηρία</span>) 7:10; 12:10; 19:1.—LMarshall, Challenge of NT Ethics ’47, 248–66; HHaerens, <span class=\"greek\">Σωτήρ</span> et <span class=\"greek\">σωτηρία</span> dans la religion grecque: Studia Hellenistica 5, ’48, 57–68; FDölger, Ac 6, ’50, 257–63.—DELG s.v. <span class=\"greek\">σῶς</span>. RLoewe, JTS 32, ’81, 341–68 (inscr. pp. 364–68). DBS XI 486–739. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0351-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σωτήριος, ον</h1><div class=\"entry-meta\"><span>adjetivo e substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σωτήριος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">σωτήρ</span>; Trag., Thu.+; inscr., pap., LXX; TestJob 51:4; Test12Patr, Philo, Joseph.; Just., D. 13, 1; 24, 1; 74, 3) relativo à salvação, salvífico, libertador, preservador, que traz salvação.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> como adj. <span class=\"greek\">ἐπεφάνη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σωτήριος</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ἀνθρώποις</span> manifestou-se a graça de Deus, trazendo salvação a todos os seres humanos (<span class=\"greek\">ς</span>. <span class=\"greek\">τινι</span> como Thu. 7, 64, 2 <span class=\"greek\">τοῖς</span> <span class=\"greek\">ξύμπασι</span> <span class=\"greek\">σωτήριος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:11</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> subst., neut. <span class=\"greek\">τὸ</span> <span class=\"greek\">σωτήριον</span> meio de libertação, depois também a própria libertação (Aeschyl. et al.; Plut., Lucian; Herm. Wr. 10, 15 <span class=\"greek\">τοῦτο</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">σωτήριον</span> <span class=\"greek\">ἀνθρώπῳ</span> <span class=\"greek\">ἐστίν</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">γνῶσις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; LXX; Jos., Bell. 3, 171; 6, 310 [<span class=\"greek\">τὰ</span> <span class=\"greek\">σωτήρια</span> de Deus]; Just., D. 74, 3b.—<span class=\"greek\">ταπεινοφρονσύνης</span> <span class=\"greek\">ς</span>[<span class=\"greek\">ω</span>]<span class=\"greek\">τ̣ή</span>[<span class=\"greek\">ρ</span>]<span class=\"greek\">ιον</span> Did., Gen. 70, 26), em nossa literatura da salvação messiânica e daquele que a medeia. Dg 12:9. Com gen. <span class=\"greek\">τὸ</span> <span class=\"greek\">σωτήριον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (TestSim 7:1; cf. TestDan 5:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:6</a> (Is 40:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:28</a>; 1 Cl 35:12 (Ps 49:23); cf. 18:12 (Ps 50:14); <span class=\"greek\">περικεφαλαία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σωτηρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:17</a> (Is 59:17). <span class=\"greek\">θήσομαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σωτηρίῳ</span> 1 Cl 15:6 (v.l. <span class=\"greek\">σωτηρίᾳ</span>=Ps 11:6).—Também do próprio <span class=\"greek\">σωτήρ</span> <span class=\"greek\">εὕρομεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σωτήριον</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">Χρ</span>. 36:1. <span class=\"greek\">εἶδον</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀφθαλμοί</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σωτήριόν</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:30</a>.—ELohse, Passafest, ’53, 50–56 (‘oferta pacífica’ em algumas passagens da LXX).—DELG s.v. <span class=\"greek\">σῶς</span>. M-M. TW. Spicq.</p></section></article>"};
